#!/bin/bash
# Intel Mac guest kit for UTM's "OpenGL Passthrough" (VMware SVGA II) option.
#
# Builds, for one guest (snowleopard, lion ... highsierra):
#   EFI.img                - OpenCore boot disk, generated by VirtualIntelMac's own
#                            build-opengl-firmware.py (VMsvga2/VMsvga2Accel with the
#                            per-guest renderer personality, QemuUSBTablet, audio).
#   GuestTools.iso         - VirtualIntelMac's guest OpenGL payload + install.command.
#   CODE.fd / VARS.fd      - VirtualIntelMac's OVMF pair (optional; UTM's own UEFI
#                            firmware also boots EFI.img).
#
# Everything comes from VirtualIntelMacOnAppleSilicon (MIT) at a pinned commit;
# only VMsvga2.kext is recompiled for Retina guests (Lion .. High Sierra, see below).
# Run on the Mac host:  ./build-kit.sh snowleopard [outdir]
set -euo pipefail

VIM_REPO=https://github.com/nfzerox/VirtualIntelMacOnAppleSilicon.git
VIM_COMMIT=2861da9e265e557aef90319e4451487ed1fed553   # VirtualIntelMac 2.2

# SDK: the phracker period SDK (sha256-pinned) the Retina VMsvga2 is built with. Where the
# guest's own SDK there lacks the guest's real kernel ABI, a later one is used with the guest
# as deployment target (Lion, Yosemite) or one header is corrected (Sierra); the result's kernel
# imports match VirtualIntelMac's own prebuilt driver for that guest.
GUEST=${1:-}
SDK=""
case "$GUEST" in
  snowleopard)  LABEL="Snow Leopard";  VERSION=10.6 ;;
  lion)         LABEL="Lion";          VERSION=10.7  SDK=10.8 ;;
  mountainlion) LABEL="Mountain Lion"; VERSION=10.8  SDK=10.8 ;;
  mavericks)    LABEL="Mavericks";     VERSION=10.9  SDK=10.9 ;;
  yosemite)     LABEL="Yosemite";      VERSION=10.10 SDK=10.11 ;;
  elcapitan)    LABEL="El Capitan";    VERSION=10.11 SDK=10.11 ;;
  sierra)       LABEL="Sierra";        VERSION=10.12 SDK=10.12 ;;
  highsierra)   LABEL="High Sierra";   VERSION=10.13 SDK=10.13 ;;
  *) echo "usage: $0 snowleopard|lion|mountainlion|mavericks|yosemite|elcapitan|sierra|highsierra [output-dir]" >&2; exit 64 ;;
esac
case "$SDK" in
  10.8)  SDK_SHA=7008e89e154244b9bb7099c92fc5a04d0ab33897e42f36fc00d563b25a187d9f ;;
  10.9)  SDK_SHA=fcf88ce8ff0dd3248b97f4eb81c7909f2cc786725de277f4d05a2b935cc49de0 ;;
  10.11) SDK_SHA=d080fc672d94f95eb54651c37ede80f61761ce4c91f87061e11a20222c8d00c8 ;;
  10.12) SDK_SHA=b314704d85934481c9927a0450db1768baf9af9efe649562fcb1a503bb44512f ;;
  10.13) SDK_SHA=1d2984acab2900c73d076fbd40750035359ee1abe1a6c61eafcd218f68923a5a ;;
esac
HERE=$(cd "$(dirname "$0")" && pwd)
OUT=${2:-"$PWD/IntelGuestKit-$GUEST"}
[ -e "$OUT" ] && { echo "$OUT already exists" >&2; exit 1; }

# build-opengl-firmware.py needs Python >= 3.11 (hashlib.file_digest).
PY=""
for c in python3.14 python3.13 python3.12 python3.11 python3; do
  p=$(command -v "$c" || true)
  [ -n "$p" ] && "$p" -c 'import sys; sys.exit(sys.version_info < (3, 11))' && { PY=$p; break; }
done
[ -n "$PY" ] || { echo "Python 3.11 or newer is required (brew install python)" >&2; exit 1; }

WORK=$(mktemp -d -t intel-guest-kit)
trap 'rm -rf "$WORK"' EXIT

echo "==> Fetching VirtualIntelMac $VIM_COMMIT (only the files the kit needs)"
git clone -q --filter=blob:none --no-checkout "$VIM_REPO" "$WORK/vim"
P=Source/prebuilt/PassthroughOpenGL
git -C "$WORK/vim" checkout -q "$VIM_COMMIT" -- \
  Source/scripts Source/compat/PassthroughOpenGLBootPolicy.h \
  Source/vendor/app-firmware-inputs.tar.gz Source/vendor/patches \
  Source/vendor/opengl-opencore-source.tar.xz Source/vendor/opengl-opencore-source.sha256 \
  Source/vendor/opengl-opencore-metadata-source.tar.xz Source/vendor/opengl-opencore-metadata-source.sha256 \
  Source/prebuilt/firmware/OVMF_CODE.fd \
  "$P/common" "$P/Firmware" "$P/$GUEST" LICENSE

if [ -n "$SDK" ]; then
  # UTM change (vmsvga2-hidpi-modes.patch): on a HiDPI panel VMsvga2 offers several Retina
  # modes and publishes its full mode list after a host-requested switch, so System
  # Preferences -> Displays -> Scaled switches the resolution. VMsvga2.kext is rebuilt with
  # VirtualIntelMac's own build-opengl-kernel.py; VMsvga2Accel stays VirtualIntelMac's
  # prebuilt (class layout unchanged).
  echo "==> Building VMsvga2.kext with the Retina mode list (needs Xcode or its Command Line Tools)"
  git -C "$WORK/vim" checkout -q "$VIM_COMMIT" -- Source/vendor/source/VMsvga2
  git -C "$WORK/vim" apply "$HERE/vmsvga2-hidpi-modes.patch"
  curl -sfL -o "$WORK/sdk.tar.xz" "https://github.com/phracker/MacOSX-SDKs/releases/download/11.3/MacOSX$SDK.sdk.tar.xz"
  echo "$SDK_SHA  $WORK/sdk.tar.xz" | shasum -a 256 -c - >/dev/null \
    || { echo "$SDK SDK checksum mismatch" >&2; exit 1; }
  tar -xf "$WORK/sdk.tar.xz" -C "$WORK"
  if [ "$GUEST" = sierra ]; then
    # Sierra 10.12.4+ uses IOFramebuffer's reserved slot 1 for setGammaTable(..., syncToVBL);
    # the 10.12.0 SDK header still marks it unused. Declare it as the shipping kernel has it.
    "$PY" -I - "$WORK/MacOSX10.12.sdk/System/Library/Frameworks/Kernel.framework/Headers/IOKit/graphics/IOFramebuffer.h" <<'PYEOF'
import sys
f = sys.argv[1]; t = open(f).read()
old = '    OSMetaClassDeclareReservedUnused(IOFramebuffer, 1);\n'
assert t.count(old) == 1
open(f, 'w').write(t.replace(old, 'public:\n    virtual IOReturn setGammaTable( UInt32 channelCount, UInt32 dataCount,\n'
    '                                   UInt32 dataWidth, void * data, bool syncToVBL );\n'
    '    OSMetaClassDeclareReservedUsed(IOFramebuffer, 1);\nprivate:\n'))
PYEOF
  fi
  # VMsvga2Accel needs probe headers outside the kit's checkout; only VMsvga2 is used, so its failure is expected.
  "$PY" -I "$WORK/vim/Source/scripts/build-opengl-kernel.py" --sdk "$WORK/MacOSX$SDK.sdk" --guest-version "$VERSION" \
    --cc "$(xcrun -f clang)" --output "$WORK/kernel" >"$WORK/kernel.log" 2>&1 || true
  K="$WORK/kernel/VMsvga2.kext/Contents/MacOS/VMsvga2"
  [ -f "$K" ] && lipo "$K" -verify_arch x86_64 || { cat "$WORK/kernel.log" >&2; echo "VMsvga2 build failed" >&2; exit 1; }
  cp "$K" "$WORK/vim/$P/$GUEST/Kernel/VMsvga2.kext/Contents/MacOS/VMsvga2"
fi

if [ "$GUEST" = snowleopard ]; then
  # UTM change (vim-guest-padded-self-view.patch): Quartz GL samples a window's own backing
  # (the masked self-copy behind a pulsing default button) with the backing's padded size,
  # which VirtualIntelMac's live drawable view rejected, so it sampled a stale CPU image
  # (frozen pulse, bold "OK"). Rebuild the x86_64 slices of GLEngine and
  # libVIMPassthroughOpenGL from source with the fix; i386 stays VirtualIntelMac's prebuilt.
  # The 10.9 SDK stubs record ApplicationServices 64.0.0; fix-dylib-compat.py lowers it to
  # 10.6's 1.0.0, or dyld refuses the engine ("invalid code module").
  echo "==> Rebuilding the x86_64 PassthroughOpenGL guest pair with the Quartz GL self-view fix"
  git -C "$WORK/vim" checkout -q "$VIM_COMMIT" -- Source/PassthroughOpenGL Source/compat Source/probes \
    Source/vendor/source/VMsvga2
  git -C "$WORK/vim" apply "$HERE/vim-guest-padded-self-view.patch"
  for s in 10.9:fcf88ce8ff0dd3248b97f4eb81c7909f2cc786725de277f4d05a2b935cc49de0 \
           10.6:ad93f3e25c1ee71e457ced1a9c106c2e6741afb96252f259a5b7c625d1156fe8; do
    v=${s%%:*}
    curl -sfL -o "$WORK/gl-sdk.tar.xz" "https://github.com/phracker/MacOSX-SDKs/releases/download/11.3/MacOSX$v.sdk.tar.xz"
    echo "${s#*:}  $WORK/gl-sdk.tar.xz" | shasum -a 256 -c - >/dev/null || { echo "$v SDK checksum mismatch" >&2; exit 1; }
    mkdir -p "$WORK/gl-sdk"; tar -xf "$WORK/gl-sdk.tar.xz" -C "$WORK/gl-sdk"; rm "$WORK/gl-sdk.tar.xz"
  done
  B="$WORK/vim/Source/scripts/build-opengl-guest-gl-pair"
  n=$(grep -n '^install_name_tool -change' "$B" | cut -d: -f1)
  head -n "$n" "$B" | sed -e 's/ -arch i386//' -e 's/ -Werror / -Wno-error /' > "$WORK/vim/Source/scripts/build-gl-pair-x64"
  chmod +x "$WORK/vim/Source/scripts/build-gl-pair-x64"
  VIM_OPENGL_CC="$(xcrun -f clang)" VIM_OPENGL_SDK="$WORK/gl-sdk/MacOSX10.9.sdk" VIM_OPENGL_WIRE_SDK="$WORK/gl-sdk/MacOSX10.9.sdk" \
  VIM_OPENGL_DISPATCH_SDK="$WORK/gl-sdk/MacOSX10.6.sdk" VIM_OPENGL_MIN_VERSION=10.6 VIM_GUEST_GL_PAIR_BUILD="$WORK/gl-pair" \
    "$WORK/vim/Source/scripts/build-gl-pair-x64" >"$WORK/gl-pair.log" 2>&1 || { tail -40 "$WORK/gl-pair.log" >&2; echo "guest GL build failed" >&2; exit 1; }
  for b in GLEngine libVIMPassthroughOpenGL.dylib; do
    G="$WORK/vim/$P/$GUEST/GuestTools/$b"
    lipo "$G" -replace x86_64 "$WORK/gl-pair/$b" -output "$WORK/$b.fixed"
    "$PY" -I "$HERE/fix-dylib-compat.py" "$WORK/$b.fixed"
    codesign --force --sign - --digest-algorithm=sha1,sha256 "$WORK/$b.fixed"
    mv "$WORK/$b.fixed" "$G"
  done
fi

echo "==> Building the $LABEL OpenCore disk (VirtualIntelMac build-opengl-firmware.py)"
PYTHONPATH="$WORK/vim/Source/scripts" "$PY" "$WORK/vim/Source/scripts/build-opengl-firmware.py" \
  --guest "$GUEST" --output "$WORK/firmware" >/dev/null

# The VM already has QEMU's isa-applesmc. With VirtualSMC loaded too, AppleSMC talks to
# VirtualSMC, whose replies time out under emulation (SMC::waitForKeyDone); when the OSK1
# read is hit, Dont Steal Mac OS X decrypts protected binaries with a bad key and loginwindow,
# mds and backupd crash at launch for the whole boot (grey screen). QEMU's SMC answers in time.
echo "==> Disabling VirtualSMC in the OpenCore disk (QEMU provides the SMC)"
DEV=$(hdiutil attach -nomount -imagekey diskimage-class=CRawDiskImage "$WORK/firmware/EFI.img" | awk '/EFI/ {print $1}')
MNT="$WORK/efi-mnt"; mkdir -p "$MNT"
diskutil mount -mountPoint "$MNT" "$DEV" >/dev/null
OCC="$MNT/EFI/OC/config.plist"
i=0
while BUNDLE=$(/usr/libexec/PlistBuddy -c "Print :Kernel:Add:$i:BundlePath" "$OCC" 2>/dev/null); do
  [ "$BUNDLE" = VirtualSMC.kext ] && /usr/libexec/PlistBuddy -c "Set :Kernel:Add:$i:Enabled false" "$OCC"
  i=$((i + 1))
done
/usr/libexec/PlistBuddy -c "Print :Kernel:Add" "$OCC" | grep -A2 -B1 VirtualSMC
diskutil unmount "$MNT" >/dev/null
hdiutil detach "${DEV%s*}" >/dev/null

echo "==> Building GuestTools.iso"
ISO="$WORK/iso"; T="$WORK/vim/$P/$GUEST/GuestTools"
mkdir -p "$ISO/Payload"
cp "$T/GLEngine" "$T/libVIMPassthroughOpenGL.dylib" "$ISO/Payload/"
cp -R "$T/VMsvga2GA.plugin" "$ISO/Payload/"
# VirtualIntelMac's display-density agent: selects the 2x mode after a host (window) resize.
if [ -f "$T/opengl-display-agent" ]; then
  cp "$T/opengl-display-agent" "$T/com.virtualintelmac.opengl-display.plist" "$ISO/Payload/"
  chmod 755 "$ISO/Payload/opengl-display-agent"
fi
# VirtualIntelMac's guest helpers for UTM's text clipboard sharing: the root agent (QGA
# protocol on COM2) and the clipboard helper (COM1, started in the user's session).
if [ -f "$T/opengl-guest-agent" ] && [ -f "$T/guest-clipboard" ]; then
  cp "$T/opengl-guest-agent" "$T/guest-clipboard" "$ISO/Payload/"
  cp "$HERE/com.utmapp.intel-guest-agent.plist" "$ISO/Payload/"
  chmod 755 "$ISO/Payload/opengl-guest-agent" "$ISO/Payload/guest-clipboard"
fi
cp "$HERE/install.command" "$ISO/Install.command"
sed -e "s/@GUEST@/$GUEST/; s/@VERSION@/$VERSION/" -i '' "$ISO/Install.command"
chmod 755 "$ISO/Install.command" "$ISO/Payload/GLEngine" "$ISO/Payload/libVIMPassthroughOpenGL.dylib" \
  "$ISO/Payload/VMsvga2GA.plugin/Contents/MacOS/VMsvga2GA"
cp "$WORK/vim/LICENSE" "$ISO/LICENSE-VirtualIntelMac.txt"
cp "$HERE/README.md" "$ISO/ReadMe.md"
hdiutil makehybrid -quiet -hfs -iso -joliet -default-volume-name "UTM Guest Kit" -o "$WORK/GuestTools.iso" "$ISO"

mkdir -p "$OUT"
mv "$WORK/firmware/EFI.img" "$WORK/firmware/CODE.fd" "$WORK/firmware/VARS.fd" "$WORK/GuestTools.iso" "$OUT/"
cp "$WORK/firmware/BuildReceipt.plist" "$OUT/FirmwareReceipt.plist"
echo "$VIM_COMMIT" > "$OUT/VirtualIntelMac-commit.txt"
echo "==> Done: $OUT"
ls -l "$OUT"
